import{_ as o,l as r,o as e,c as s,v as t,p as d,x as l,d as n,i as p,S as _}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"DDPM","description":"","frontmatter":{"title":"DDPM","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ddpm.md","filePath":"llm/ddpm.md","lastUpdated":1789023840000}'),m={name:"llm/ddpm.md"};function h(c,a,D,f,u,x){const i=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="ddpm" tabindex="-1">DDPM <a class="header-anchor" href="#ddpm" aria-label="Permalink to &quot;DDPM&quot;">​</a></h1><div class="epigraph"><p>把图像逐步加噪到近高斯，再学每一步把噪声减回去。采样就是沿同一条马尔可夫链倒着走。</p><footer>—— Ho, Jain, Abbeel, Denoising Diffusion Probabilistic Models</footer></div><p><a href="/llm/multimodal-reasoning">上一课</a>收束理解。本单元问像素如何生成。理解侧走连续 <a href="/llm/vit-as-encoder">ViT</a> 前缀；生成常从噪声出发。缺口是去噪扩散这条链。后课流匹配默认：离散时间、预测噪声，不是唯一的连续生成几何。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接在像素上回归整图会模糊；GAN 锐但不给似然、训练脆。Sohl-Dickstein 等的扩散把数据破坏与恢复写成马尔可夫链。Ho 等人的 DDPM 把它训成可扩展的图像生成器：前向</p> \\[q(x_t\\mid x_{t-1})=\\mathcal{N}(\\sqrt{1-\\beta_t}x_{t-1},\\beta_t I) \\]<p>\\(t=1\\ldots T\\) 后 \\(x_T\\) 近标准正态。反向用网络 \\(\\epsilon_\\theta(x_t,t)\\) 预测所加噪声，等价于学高斯反向步。缺口不是再讲卷积骨干，而是这条目标比对抗稳、比逐像素似然可扩展。</p><p><span class="marginnote">训练目标是对 \\(t\\) 与噪声的期望 MSE，不必每步算完整 ELBO。采样仍要走许多步，\\(T\\) 常数百到千，这是后课蒸馏要砍的税。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：抽 \\(x_0\\)、时间 \\(t\\)、噪声 \\(\\epsilon\\)，构造 \\(x_t\\)，回归 \\(\\epsilon\\)。采样：从 \\(x_T\\sim\\mathcal{N}(0,I)\\) 逐步更新到 \\(x_0\\)。条件生成把类或文本嵌入送进 \\(\\epsilon_\\theta\\)（后课 CFG 再加压）。验收用 FID / 人评，不要用 <a href="/llm/clip">CLIP</a> 检索分代替生成质量。</p>',10)),(e(),d(_,null,{default:l(()=>[p(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20LR%0A%20%20X0%5B%22%E6%95%B0%E6%8D%AE%20x0%22%5D%20--%3E%20XT%5B%22%E5%99%AA%E5%A3%B0%20xT%22%5D%0A%20%20XT%20--%3E%20DEN%5B%22%E9%80%90%E6%AD%A5%E5%8E%BB%E5%99%AA%22%5D%0A%20%20DEN%20--%3E%20XHAT%5B%22%E7%94%9F%E6%88%90%20x0%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每步只去掉一点噪声，网络学的是向量场在不同噪声水平上的值。高频先毁、后恢复，这与 VQ 像素损失抹掉高频不同：扩散在采样末端仍可写细节，但步数换质量。与离散 <a href="/llm/vqgan">VQGAN</a> 码上的 AR 相比，这里没有词表，似然在连续空间上以变分形式出现。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>像素空间 DDPM 分辨率贵、步数多。下一课把离散链换成连续时间的流，路径可以更直。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DDPM 用加噪链与预测噪声训练可采样的生成器。</li><li>目标是 MSE，采样步数是质量税。</li><li>无离散视觉词表，与理解用的 patch 前缀不是同一接口。</li><li>出处：Ho, Jain, Abbeel, DDPM。</li></ul>',6))])}const T=o(m,[["render",h]]);export{E as __pageData,T as default};
